using System.Security.Cryptography; using System.Text; using IptvManagement.Application.Abstractions; using Microsoft.AspNetCore.DataProtection;
namespace IptvManagement.Infrastructure.Security;
public class TokenService:ITokenService{ public string CreateSecureToken(){ var bytes=RandomNumberGenerator.GetBytes(32); return Convert.ToBase64String(bytes).Replace('+','-').Replace('/','_').TrimEnd('='); } public string HashToken(string token)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(token))); public bool Verify(string token,string hash)=>CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(HashToken(token)),Encoding.UTF8.GetBytes(hash)); }
public class StreamUrlProtector(IDataProtectionProvider provider):IStreamUrlProtector{ readonly IDataProtector p=provider.CreateProtector("IptvManagement.StreamUrls.v1"); public string Protect(string streamUrl)=>p.Protect(streamUrl); public string Unprotect(string encrypted)=>p.Unprotect(encrypted); public string Mask(string streamUrl){ if(!Uri.TryCreate(streamUrl,UriKind.Absolute,out var uri)) return "[geschützt]"; return $"{uri.Scheme}://{uri.Host}/…"; }}
